mapper.select:
SELECT COALESCE(SUM(
    CASE
        WHEN transaction_type IN ('SALARY', 'OTHER_IN') THEN amount
        WHEN transaction_type IN ('EXPENSE', 'REMITTANCE', 'OTHER_OUT') THEN -amount
        ELSE 0
    END
), 0)
FROM transaction_history
WHERE member_id = #{memberId}
  AND transaction_at >= #{since}
